function countUsers() {
  return new Promise((resolve, reject) => {
    let unsubscribe = null;
    let settled = false;
    unsubscribe = subscribeToUsers(
      (users) => {
        if (settled) return;
        settled = true;
        resolve(users.length);
        queueMicrotask(() => unsubscribe?.());
      },
      (err) => reject(err)
    );
  });
}
